export const etfPremiumDefinitions={etfPremium:{title:'Compare NAV change with the prices paid and received',fields:[
  ['premiumCash','Cash spent on the hypothetical purchase (CAD)',10000,100,1000000,1000],
  ['premiumStartNav','NAV per unit at the purchase comparison point (CAD)',100,1,10000,1],
  ['premiumNavChange','Change in NAV per unit over the interval (%)',5,-50,50,1],
  ['premiumEntry','Entry market price versus same-point NAV: premium +, discount − (%)',2,-5,5,.25],
  ['premiumExit','Exit market price versus same-point NAV: premium +, discount − (%)',-1,-5,5,.25]
]}};
export function etfPremiumLedger(input,entry=input.premiumEntry,exit=input.premiumExit){
  const entryFactor=1+entry/100,exitFactor=1+exit/100,navFactor=1+input.premiumNavChange/100;
  const buyPrice=input.premiumStartNav*entryFactor,endNav=input.premiumStartNav*navFactor,sellPrice=endNav*exitFactor,units=input.premiumCash/buyPrice;
  const initialNavValue=units*input.premiumStartNav,endNavValue=units*endNav,proceeds=units*sellPrice;
  const marketReturn=navFactor*exitFactor/entryFactor-1;
  return {buyPrice,endNav,sellPrice,units,initialNavValue,endNavValue,proceeds,marketReturn,returnGap:marketReturn-input.premiumNavChange/100,entryAdjustment:initialNavValue-input.premiumCash,navGrowth:endNavValue-initialNavValue,exitAdjustment:proceeds-endNavValue};
}
export function etfPremiumResult(kind,input){
  if(kind!=='etfPremium')throw Error('Unknown ETF-premium topic.');
  const p=etfPremiumLedger(input);
  return {metrics:[['Market-price change from purchase to sale in this example',p.marketReturn,'percent'],['Sale proceeds before any excluded fees or tax',p.proceeds,'money'],['Market-price change minus NAV change',p.returnGap,'pp']],note:'Original hypothetical CAD example with a full purchase and sale, fixed units and no cash distributions. Each market price is compared with a synchronized NAV at its own teaching point. Positive percentages mean a premium and negative percentages a discount. Fractional units are retained mathematically, without promising a broker can execute that quantity. No bid–ask spread, commission, separate expense deduction, tax, currency conversion, settlement delay or new cash flow is added. NAV change is a selected price change, not a total-return or annual-return forecast. No ETF, actual quote, current premium, historical spread or future exit opportunity is estimated.',charts:[
    {id:'etf-premium-price-pairs',type:'groupbar',title:'Compare each market price with the NAV at the same point',unit:'money',unitLabel:'CAD per unit · synchronized hypothetical comparisons',seriesNames:['NAV per unit','Market execution price per unit'],rows:[{label:'Purchase comparison point',values:[input.premiumStartNav,p.buyPrice]},{label:'Sale comparison point',values:[p.endNav,p.sellPrice]}],note:'Purchase price = starting NAV × (1 + entry premium). Sale price = ending NAV × (1 + exit premium). A negative premium input is a discount. The interval has no specified length and no annualisation. These matched teaching values do not justify comparing a live market quote with an older published NAV.'},
    {id:'etf-premium-exit-sensitivity',type:'line',title:'The eventual exit premium or discount changes the trading return',unit:'percent',unitLabel:'Market-price change over the selected interval · no distributions or annualisation',xLabel:'Exit premium / discount (%)',xMin:-5,xTicks:[-5,0,5].map(value=>({value,label:(value>0?'+':'')+value+'%'})),series:[{name:'Market-price change at different exit premia',rows:Array.from({length:41},(_,i)=>{const x=-5+i*.25;return {x,value:etfPremiumLedger(input,input.premiumEntry,x).marketReturn};})},{name:'Selected NAV change, as a separate price comparison',dash:true,rows:[{x:-5,value:input.premiumNavChange/100},{x:5,value:input.premiumNavChange/100}]},{name:'Selected exit assumption · gold point',rows:[{x:input.premiumExit,value:p.marketReturn}]}],note:'Only the exit premium changes along the horizontal axis. The entry premium and NAV change stay selected. The line crosses the NAV-change comparison when exit premium equals entry premium. A premium is not automatically a fee lost every interval: what happens at both transaction points matters. No probability or promised convergence to NAV is attached to this curve.'},
    {id:'etf-premium-proceeds-bridge',type:'waterfall',title:'Reconcile the purchase cash with NAV exposure and final sale proceeds',unit:'money',rows:[{label:'Cash paid for the fixed unit holding',value:input.premiumCash},{label:'Entry-price adjustment to initial NAV exposure',value:p.entryAdjustment},{label:'Change in NAV value of those same units',value:p.navGrowth},{label:'Exit-price adjustment from final NAV to proceeds',value:p.exitAdjustment}],totalLabel:'Sale proceeds before excluded costs',note:'The entry step changes the measurement from cash paid at market price to the NAV value of the units obtained; it is not a second commission or a new cash withdrawal. The final step changes ending NAV value to sale proceeds. Negative entry adjustment reflects paying a premium, while a discount produces a positive adjustment. This is an attribution bridge across two valuation bases, not four separate account transactions.'},
    {id:'etf-premium-entry-exit-matrix',type:'heatmap',title:'Match the entry and exit assumptions before interpreting the NAV gain',unit:'percent',signed:true,unitLabel:'Market-price change · selected NAV change retained',columns:['−2%','0%','+2%','+4%'],rows:[-2,0,2,4].map(entry=>({label:(entry>0?'+':'')+entry+'% in',values:[-2,0,2,4].map(exit=>etfPremiumLedger(input,entry,exit).marketReturn)})),note:'Rows replace the entry premium or discount and columns replace the exit premium or discount. The selected NAV change stays fixed; starting cash and NAV level affect dollar values but not these price-change percentages. Along equal-premium cells, market-price change equals NAV change. A discount at purchase does not assure a gain: NAV can fall or the exit discount can widen.'}
  ]};
}
